@@ -321,6 +322,41 @@ void PipeGpuResources::initializeForDevice(int device, PipeCluster *pc){
     size_t total;
     cudaMemGetInfo(&avail, &total);
     printf("Available GPU memory : %zu * 1024 * 1024\n", avail/(1024*1024ll));
+
+    // kMaxDeviceMem (70 GiB) was sized for >=96 GB GPUs. On an 80 GB H100 it
+    // leaves <2 GiB free, and the QG compute path's grow-on-demand scratch
+    // (PipeQueryGroup.cu: dist/A/ynorm, ~5-10 GB) then dies in cudaMalloc --
+    // see the 2026-07-17 e2e_rummy_qg_* OOM logs. Cap the page pool so that
+    // QG_POOL_RESERVE_GB (GiB, default 14) of what is free RIGHT NOW stays
+    // free for that scratch (the temp stack, cuBLAS handle and CUDA context
+    // are already allocated at this point, so `avail` accounts for them).
+    // On a >=96 GB card avail-reserve exceeds kMaxDeviceMem and this is a
+    // no-op, keeping the paper's RTX PRO 6000 configuration unchanged.
+    const size_t reserve = [] {
+        const char* e = getenv("QG_POOL_RESERVE_GB");
+        double gb = (e != nullptr) ? atof(e) : 14.0;
+        if (gb < 0.0)
+            gb = 0.0;
+        return (size_t)(gb * 1024.0 * 1024.0 * 1024.0);
+    }();
+    FAISS_THROW_IF_NOT_FMT(
+            avail > reserve + pageSize_,
+            "PipeGpuResources: only %zu MiB free, but QG_POOL_RESERVE_GB "
+            "reserves %zu MiB -- no room left for even one cluster page",
+            avail / (1024 * 1024),
+            reserve / (1024 * 1024));
+    const size_t clamped =
+            std::min(MaxDeviceSize_, (avail - reserve) / pageSize_ * pageSize_);
+    if (clamped < MaxDeviceSize_) {
+        printf("PipeGpuResources: page pool clamped %zu MiB -> %zu MiB "
+               "(reserving %zu MiB for QG scratch; override with "
+               "QG_POOL_RESERVE_GB)\n",
+               MaxDeviceSize_ / (1024 * 1024),
+               clamped / (1024 * 1024),
+               reserve / (1024 * 1024));
+        MaxDeviceSize_ = clamped;
+    }
+
     void* p = nullptr;
     auto err = cudaMalloc(&p, MaxDeviceSize_);
